`python3 -c "
import os,re
roots=['<RUN>','<RUN>/slots/a/home/.cursor']
pat=re.compile(r'AskQuestion|ask_question|ask-question|askQuestion',re.I)
skip={'.git','node_modules'}
for root in roots:
  for dirpath, dirnames, filenames in os.walk(root):
    dirnames[:]=[d for d in dirnames if d not in skip]
    for f in filenames:
      p=os.path.join(dirpath,f)
      try:
        if os.path.getsize(p)>20_000_000: continue
        with open(p,'rb') as fh:
          data=fh.read()
        if not pat.search(data.decode('utf-8','ignore')): continue
        text=data.decode('utf-8','ignore')
        for i,line in enumerate(text.splitlines(),1):
          if pat.search(line):
            print(f'{p}:{i}:{line.strip()[:400]}')
      except Exception:
        pass
"
